        # 2) Nettoyage accents
        def clean_text(x):
            if isinstance(x, str):
                try:
                    return x.encode("latin1").decode("utf-8").strip()
                except:
                    return x.strip()
            return x

        df = df.applymap(clean_text)
        df.columns = [clean_text(c) for c in df.columns]

        # 3) Vérification colonne de dates
        if "Nom_colonne" not in df.columns:
            return {
                "error": "Colonne 'Nom_colonne' absente.",
                "colonnes_detectees": df.columns.tolist(),
            }

        try:
            df["Nom_colonne"] = pd.to_datetime(df["Nom_colonne"], dayfirst=True)
        except:
            return {
                "error": "Impossible de convertir les dates.",
                "exemples": df["Nom_colonne"].head().tolist(),
            }

        # 4) Construction JSON structuré
        data_json = {
            "columns": df.columns.tolist(),
            "dates": df["Nom_colonne"].dt.strftime("%Y-%m").tolist(),
            "data": {},
        }

        for col in df.columns:
            if col != "Nom_colonne":
                cleaned = pd.to_numeric(df[col], errors="coerce").fillna(0).tolist()
                data_json["data"][col] = cleaned

        return data_json

