    def budget_extract_series(
        self, aggregate: str = Field(..., description="Nom ou mot-clé de l’agrégat.")
    ) -> dict:

        prepared = self.budget_prepare_csv()
        if "error" in prepared:
            return prepared

        aggregates = list(prepared["data"].keys())

        # Recherche fuzzy simple
        matches = [a for a in aggregates if aggregate.lower() in a.lower()]

        if not matches:
            return {
                "error": f"Aucun agrégat correspondant trouvé pour : {aggregate}",
                "agrégats_disponibles": aggregates,
            }

        col = matches[0]

        return {
            "aggregate": col,
            "dates": prepared["dates"],
            "values": prepared["data"][col],
        }

