    def budget_compute_stats(
        self,
        dates: list = Field(..., description="Dates AAAA-MM."),
        values: list = Field(..., description="Valeurs numériques."),
    ) -> dict:

        arr = pd.to_numeric(values, errors="coerce").fillna(0).values

        return {
            "min_value": float(arr.min()),
            "min_date": dates[int(arr.argmin())],
            "max_value": float(arr.max()),
            "max_date": dates[int(arr.argmax())],
            "mean_value": float(arr.mean()),
        }
